screenPanels.initJs:
function(container, apiUrl, tables) {
  // 店舗データの初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#prediction-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">予測結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID || ''}">
        <td>${result.商品コード || '-'}</td>
        <td>${result.商品名 || '-'}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591896813')">発注量計算</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart() {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = ['1/1', '1/2', '1/3', '1/4', '1/5', '1/6', '1/7'];
    const actualData = [120, 135, 98, 156, 142, 178, 165];
    const predictedData = [125, 140, 95, 160, 145, 175, 170];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const maxValue = Math.max(...actualData, ...predictedData) * 1.1;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績データの描画
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actualData.forEach((value, index) => {
      const x = padding + (index * chartWidth) / (dates.length - 1);
      const y = canvas.height - padding - (value / maxValue) * chartHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 予測データの描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    predictedData.forEach((value, index) => {
      const x = padding + (index * chartWidth) / (dates.length - 1);
      const y = canvas.height - padding - (value / maxValue) * chartHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillText('予測値', padding + 100, padding - 20);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(padding, padding - 15);
    ctx.lineTo(padding + 15, padding - 15);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding + 80, padding - 15);
    ctx.lineTo(padding + 95, padding - 15);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = ['食品', '飲料', '日用品', '冷凍食品'];
    const actualValues = [85, 92, 78, 88];
    const predictedValues = [88, 89, 82, 85];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (categories.length * 2 + 1);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バーの描画
    categories.forEach((category, index) => {
      const x = padding + (index * 2 + 1) * barWidth;

      // 実績バー
      const actualHeight = (actualValues[index] / 100) * chartHeight;
      ctx.fillStyle = '#4a9eff';
      ctx.fillRect(x, canvas.height - padding - actualHeight, barWidth * 0.8, actualHeight);

      // 予測バー
      const predictedHeight = (predictedValues[index] / 100) * chartHeight;
      ctx.fillStyle = '#ff6a00';
      ctx.fillRect(x + barWidth, canvas.height - padding - predictedHeight, barWidth * 0.8, predictedHeight);

      // カテゴリ名
      ctx.fillStyle = '#d0e4ff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, x + barWidth, canvas.height - padding + 20);
    });
  }

  // バリデーション関数
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    if (!storeId) {
      return '店舗を選択してください';
    }
    if (!category) {
      return '商品カテゴリを選択してください';
    }
    if (!startDate) {
      return '予測期間の開始日を設定してください';
    }
    if (!endDate) {
      return '予測期間の終了日を設定してください';
    }
    if (!model) {
      return '予測モデルを選択してください';
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (start < today) {
      return '開始日は現在日以降の日付を設定してください';
    }
    if (start >= end) {
      return '開始日は終了日より前の日付を入力してください';
    }

    return null;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 予測実行
  container.querySelector('#btn-predict').addEventListener('click', async () => {
    const error = validateForm();
    if (error) {
      showError(error);
      return;
    }

    const btn = container.querySelector('#btn-predict');
    const originalText = btn.textContent;
    btn.textContent = '予測実行中...';
    btn.disabled = true;

    try {
      // 予測結果データの作成
      const storeId = container.querySelector('#store-select').value;
      const category = container.querySelector('#category-select').value;
      const startDate = container.querySelector('#start-date').value;
      const endDate = container.querySelector('#end-date').value;

      // サンプル予測結果データ
      const sampleResults = [
        {
          予測結果ID: 'pred-001',
          商品コード: 'P001',
          商品名: 'おにぎり（鮭）',
          現在在庫: 45,
          予測数量: 120,
          推奨発注数量: 75,
          予測精度: 92
        },
        {
          予測結果ID: 'pred-002',
          商品コード: 'P002',
          商品名: 'サンドイッチ',
          現在在庫: 23,
          予測数量: 85,
          推奨発注数量: 62,
          予測精度: 88
        }
      ];

      // 予測精度指標の更新
      container.querySelector('#accuracy-value').textContent = '90.5%';
      container.querySelector('#confidence-value').textContent = '85.2%';
      container.querySelector('#period-value').textContent = `${startDate} ～ ${endDate}`;

      // 結果表示
      container.querySelector('#prediction-results').classList.remove('hidden');
      renderPredictionResults(sampleResults);
      drawPredictionChart();
      drawComparisonChart();

      // 結果をスクロール表示
      container.querySelector('#prediction-results').scrollIntoView({ behavior: 'smooth' });

    } catch (error) {
      showError('予測処理中にエラーが発生しました');
    } finally {
      btn.textContent = originalText;
      btn.disabled = false;
    }
  });

  // エクスポート機能
  container.querySelector('#btn-export').addEventListener('click', () => {
    const results = [
      ['商品コード', '商品名', '現在在庫', '予測需要量', '推奨発注量', '予測精度'],
      ['P001', 'おにぎり（鮭）', '45', '120', '75', '92%'],
      ['P002', 'サンドイッチ', '23', '85', '62', '88%']
    ];

    const csvContent = '\uFEFF' + results.map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 再予測
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    container.querySelector('#prediction-results').classList.add('hidden');
  });

  // 初期化
  initStoreOptions();

  // 初期日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);

  container.querySelector('#start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector('#filter-user');
    if (users) {
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.ユーザー名 || '';
        option.textContent = user.ユーザー名 || '';
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      return;
    }

    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const statusClass = row.処理結果 === '成功' ? 'status-success' : 
                         row.処理結果 === '失敗' || row.処理結果 === 'エラー' ? 'status-error' : '';

      return `
        <tr data-id="${row.操作履歴ID || ''}">
          <td>${formatDateTime(row.操作日時)}</td>
          <td>${row.ユーザー名 || ''}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span class="${statusClass}">${row.処理結果 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID || ''}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePagination(rows.length);
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    pageInfo.textContent = `ページ ${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // フィルタリング処理
  function applyFilters() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const user = container.querySelector('#filter-user').value;
    const operationType = container.querySelector('#filter-operation-type').value;
    const screenName = container.querySelector('#filter-screen-name').value;
    const ipAddress = container.querySelector('#filter-ip-address').value;
    const result = container.querySelector('#filter-result').value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    // IPアドレス形式バリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert('不正なIPアドレス形式です。正しい形式で入力してください。');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = new Date(row.操作日時);
        if (startDate && rowDate < new Date(startDate)) return false;
        if (endDate && rowDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // ユーザーフィルター
      if (user && row.ユーザー名 !== user) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !row.操作画面?.includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && row.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-user').value = '';
    container.querySelector('#filter-operation-type').value = '';
    container.querySelector('#filter-screen-name').value = '';
    container.querySelector('#filter-ip-address').value = '';
    container.querySelector('#filter-result').value = '';

    filteredData = allHistoryData;
    currentPage = 1;
    renderRows(filteredData);
  }

  // CSV出力
  function exportCSV() {
    if (filteredData.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    if (filteredData.length > 100000) {
      alert('データ量が多すぎるため、CSV出力できません。検索条件を絞り込んでください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredData.map(row => [
        `"${formatDateTime(row.操作日時)}"`,
        `"${row.ユーザー名 || ''}"`,
        `"${row.操作種別 || ''}"`,
        `"${row.操作画面 || ''}"`,
        `"${row.操作対象テーブル || ''}"`,
        `"${row.操作対象ID || ''}"`,
        `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
        `"${row.IPアドレス || ''}"`,
        `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
        `"${row.処理結果 || ''}"`,
        `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
        `"${row.処理時間 || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector('#detail-datetime').textContent = formatDateTime(history.操作日時);
    container.querySelector('#detail-user').textContent = history.ユーザー名 || '';
    container.querySelector('#detail-operation-type').textContent = history.操作種別 || '';
    container.querySelector('#detail-screen').textContent = history.操作画面 || '';
    container.querySelector('#detail-target-table').textContent = history.操作対象テーブル || '';
    container.querySelector('#detail-target-id').textContent = history.操作対象ID || '';
    container.querySelector('#detail-content').textContent = history.操作内容 || '';
    container.querySelector('#detail-ip').textContent = history.IPアドレス || '';
    container.querySelector('#detail-user-agent').textContent = history.ユーザーエージェント || '';
    container.querySelector('#detail-result').textContent = history.処理結果 || '';
    container.querySelector('#detail-error').textContent = history.エラーメッセージ || '';
    container.querySelector('#detail-processing-time').textContent = history.処理時間 ? `${history.処理時間}ms` : '';

    container.querySelector('#detail-modal').classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const historyData = await window.aivicApi.list(12); // システム操作履歴テーブル
    if (historyData) {
      allHistoryData = historyData.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
      filteredData = allHistoryData;
      renderRows(filteredData);
    } else {
      renderRows([]);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-clear').addEventListener('click', clearFilters);
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadInitialData();
}

function(container, apiUrl, tables) {
  let isProcessing = false;
  let predictionResults = [];

  // 店舗データとカテゴリデータの取得
  const storeTable = tables.find(t => t.tableName === '店舗マスタ');
  const productTable = tables.find(t => t.tableName === '商品マスタ');

  // 店舗選択肢の設定
  function setupStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリチェックボックスの設定
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    // 商品マスタから商品カテゴリIDを抽出してユニークなカテゴリを作成
    const categories = new Set();
    if (productTable && productTable.records) {
      productTable.records.forEach(product => {
        if (product.商品カテゴリID) {
          categories.add(product.商品カテゴリID);
        }
      });
    }

    // デフォルトカテゴリを追加
    const defaultCategories = ['食品', '日用品', '衣料品', '家電', '書籍', '化粧品'];
    defaultCategories.forEach(cat => categories.add(cat));

    categories.forEach(categoryId => {
      const label = document.createElement('label');
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = categoryId;
      checkbox.name = 'product-categories';

      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(categoryId));
      categoryContainer.appendChild(label);
    });
  }

  // 季節要因スライダーの値表示更新
  function setupSeasonalSlider() {
    const slider = container.querySelector('#seasonal-factor');
    const valueDisplay = container.querySelector('#seasonal-value');

    slider.addEventListener('input', function() {
      valueDisplay.textContent = this.value;
    });
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    const storeSelect = container.querySelector('#store-select');
    const selectedStores = Array.from(storeSelect.selectedOptions);
    const selectedCategories = container.querySelectorAll('input[name="product-categories"]:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;

    if (!startDate) {
      errors.push('予測対象期間の開始日を入力してください');
    }

    if (!endDate) {
      errors.push('予測対象期間の終了日を入力してください');
    }

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (start < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      if (end < start) {
        errors.push('予測期間の終了日は開始日以降を指定してください');
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    if (selectedStores.length === 0) {
      errors.push('店舗を選択してください');
    }

    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    if (!learningStartDate) {
      errors.push('学習データ期間の開始日を入力してください');
    }

    if (!learningEndDate) {
      errors.push('学習データ期間の終了日を入力してください');
    }

    if (learningStartDate && learningEndDate && startDate && endDate) {
      const learningStart = new Date(learningStartDate);
      const learningEnd = new Date(learningEndDate);
      const predictionStart = new Date(startDate);
      const predictionEnd = new Date(endDate);

      const learningPeriod = Math.ceil((learningEnd - learningStart) / (1000 * 60 * 60 * 24));
      const predictionPeriod = Math.ceil((predictionEnd - predictionStart) / (1000 * 60 * 60 * 24));

      if (learningPeriod < predictionPeriod) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorContainer = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorContainer.innerHTML = '<h4>入力エラー</h4><ul>' + 
        errors.map(error => `<li>${error}</li>`).join('') + '</ul>';
      errorContainer.classList.remove('hidden');
    } else {
      errorContainer.classList.add('hidden');
    }
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');

    progressFill.style.width = percentage + '%';
    progressText.textContent = message;
  }

  // UI無効化/有効化
  function setUIEnabled(enabled) {
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      input.disabled = !enabled;
    });

    if (!enabled) {
      container.querySelector('#progress-section').classList.remove('hidden');
    } else {
      container.querySelector('#progress-section').classList.add('hidden');
    }
  }

  // 天候データ取込
  async function importWeatherData() {
    try {
      container.querySelector('#weather-status').textContent = '取込中...';

      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 実際の実装では weather API を呼び出し
      const weatherData = {
        店舗ID: 'dummy-store-id',
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '予報値',
        データソース: '気象庁API'
      };

      const weatherTableIndex = tables.findIndex(t => t.tableName === '天候データ');
      if (weatherTableIndex >= 0) {
        await window.aivicApi.save(weatherTableIndex, weatherData);
        container.querySelector('#weather-status').textContent = '取込完了';
      } else {
        throw new Error('天候データテーブルが見つかりません');
      }

    } catch (error) {
      container.querySelector('#weather-status').textContent = '取込失敗';
      showErrors(['天候データの取得に失敗しました。データソースの設定を確認してください。']);
    }
  }

  // イベントデータ取込
  async function importEventData() {
    try {
      container.querySelector('#events-status').textContent = '取込中...';

      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      const eventData = {
        店舗ID: 'dummy-store-id',
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 500,
        有効フラグ: true
      };

      const eventTableIndex = tables.findIndex(t => t.tableName === 'イベントデータ');
      if (eventTableIndex >= 0) {
        await window.aivicApi.save(eventTableIndex, eventData);
        container.querySelector('#events-status').textContent = '取込完了';
      } else {
        throw new Error('イベントデータテーブルが見つかりません');
      }

    } catch (error) {
      container.querySelector('#events-status').textContent = '取込失敗';
      showErrors(['イベントデータの取込に失敗しました。ファイル形式を確認してください。']);
    }
  }

  // AI予測実行
  async function executePrediction() {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    showErrors([]);
    isProcessing = true;
    setUIEnabled(false);

    try {
      // 進捗更新のシミュレーション
      const progressSteps = [
        { percentage: 10, message: 'データ収集中...' },
        { percentage: 30, message: '外部要因データを分析中...' },
        { percentage: 50, message: 'AIモデルを学習中...' },
        { percentage: 70, message: '需要予測を計算中...' },
        { percentage: 90, message: '結果を生成中...' },
        { percentage: 100, message: '処理完了' }
      ];

      for (const step of progressSteps) {
        updateProgress(step.percentage, step.message);
        await new Promise(resolve => setTimeout(resolve, 1000));
      }

      // 予測結果の生成（模擬データ）
      const selectedStores = Array.from(container.querySelector('#store-select').selectedOptions);
      const selectedCategories = Array.from(container.querySelectorAll('input[name="product-categories"]:checked'));
      const startDate = new Date(container.querySelector('#prediction-start-date').value);
      const endDate = new Date(container.querySelector('#prediction-end-date').value);

      predictionResults = [];

      selectedStores.forEach(storeOption => {
        selectedCategories.forEach(categoryCheckbox => {
          for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
            const result = {
              予測結果ID: crypto.randomUUID(),
              店舗ID: storeOption.value,
              店舗名: storeOption.textContent,
              商品カテゴリ: categoryCheckbox.value,
              予測対象日: new Date(d).toISOString().split('T')[0],
              予測数量: Math.floor(Math.random() * 100) + 50,
              予測精度: Math.floor(Math.random() * 30) + 70,
              推奨発注数量: Math.floor(Math.random() * 80) + 40,
              予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
              予測ステータス: '完了',
              発注済フラグ: false
            };
            predictionResults.push(result);
          }
        });
      });

      // 結果をデータベースに保存
      const resultTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');
      if (resultTableIndex >= 0) {
        for (const result of predictionResults) {
          await window.aivicApi.save(resultTableIndex, result);
        }
      }

      // 結果表示
      renderPredictionResults();
      container.querySelector('#prediction-results').classList.remove('hidden');

    } catch (error) {
      showErrors(['AI予測実行が失敗しました: ' + error.message]);
    } finally {
      isProcessing = false;
      setUIEnabled(true);
    }
  }

  // 予測結果の表示
  function renderPredictionResults() {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = predictionResults.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${result.店舗名}</td>
        <td>${result.商品カテゴリ}</td>
        <td>${result.予測対象日}</td>
        <td>${result.予測数量}</td>
        <td>${result.予測精度}%</td>
        <td>${result.推奨発注数量}</td>
        <td>
          <button class="action-btn secondary order-btn" data-id="${result.予測結果ID}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // CSVエクスポート
  function exportResultsToCSV() {
    if (predictionResults.length === 0) {
      alert('エクスポートする結果がありません');
      return;
    }

    const headers = ['店舗名', '商品カテゴリ', '予測日', '予測数量', '予測精度', '推奨発注数量'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      predictionResults.map(result => [
        result.店舗名,
        result.商品カテゴリ,
        result.予測対象日,
        result.予測数量,
        result.予測精度 + '%',
        result.推奨発注数量
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'ai_prediction_results_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  }

  // 初期化処理
  setupStoreOptions();
  setupCategoryCheckboxes();
  setupSeasonalSlider();

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastMonth = new Date(today);
  lastMonth.setMonth(lastMonth.getMonth() - 1);

  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // イベントリスナー設定
  container.querySelector('#btn-import-weather').addEventListener('click', importWeatherData);
  container.querySelector('#btn-import-events').addEventListener('click', importEventData);
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-export-results').addEventListener('click', exportResultsToCSV);
  container.querySelector('#btn-goto-order').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const resultId = orderBtn.dataset.id;
      const result = predictionResults.find(r => r.予測結果ID === resultId);
      if (result && confirm(`${result.店舗名}の${result.商品カテゴリ}について発注処理を実行しますか？`)) {
        // 発注データ作成
        const orderData = {
          店舗ID: result.店舗ID,
          商品ID: 'dummy-product-id', // 実際は商品マスタから取得
          需要予測結果ID: result.予測結果ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: result.推奨発注数量,
          予測数量: result.予測数量,
          発注単価: 100, // 仮の単価
          発注金額: result.推奨発注数量 * 100,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'dummy-supplier-id',
          発注理由: 'AI需要予測に基づく自動発注',
          自動発注フラグ: true
        };

        const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
        if (orderTableIndex >= 0) {
          const saved = await window.aivicApi.save(orderTableIndex, orderData);
          if (saved) {
            alert('発注処理が完了しました');
            // 発注済フラグを更新
            result.発注済フラグ = true;
            renderPredictionResults();
          }
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentOrders = [];
  let stores = [];
  let products = [];
  let suppliers = [];

  // 初期データの取得
  async function loadInitialData() {
    try {
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ
      products = await window.aivicApi.list(2) || []; // 商品マスタ
      suppliers = await window.aivicApi.list(2) || []; // 仕入先（商品マスタから取得）

      renderStoreOptions();
    } catch (error) {
      showError('初期データの読み込みに失敗しました');
    }
  }

  // 店舗選択肢の描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 発注データの描画
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      const statusBadge = getStatusBadge(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.発注ID}">
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" ${isDisabled}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${getSupplierName(product.仕入先ID)}</td>
          <td style="text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // 仕入先名の取得
  function getSupplierName(supplierId) {
    const supplier = suppliers.find(s => s.仕入先ID === supplierId);
    return supplier ? supplier.仕入先名 : '未設定';
  }

  // ステータスバッジの生成
  function getStatusBadge(status) {
    const statusConfig = {
      '送信待ち': { color: '#ffa500', bg: 'rgba(255, 165, 0, 0.1)' },
      '送信済み': { color: '#00c851', bg: 'rgba(0, 200, 81, 0.1)' },
      '送信失敗': { color: '#ff6a00', bg: 'rgba(255, 106, 0, 0.1)' },
      'キャンセル': { color: '#6c757d', bg: 'rgba(108, 117, 125, 0.1)' }
    };

    const config = statusConfig[status] || statusConfig['送信待ち'];
    return `<span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${config.bg}; color: ${config.color};">${status || '送信待ち'}</span>`;
  }

  // サマリー情報の更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');
    const selectedCount = checkboxes.length;

    let totalAmount = 0;
    checkboxes.forEach(cb => {
      const order = currentOrders.find(o => o.発注ID === cb.dataset.id);
      if (order) {
        totalAmount += order.発注金額 || 0;
      }
    });

    container.querySelector('#selected-count').textContent = `選択件数: ${selectedCount}件`;
    container.querySelector('#total-amount').textContent = `合計金額: ¥${totalAmount.toLocaleString()}`;
    container.querySelector('#btn-send').disabled = selectedCount === 0;
  }

  // 店舗別発注データの読み込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrders([]);
      return;
    }

    try {
      const orders = await window.aivicApi.list(7) || []; // 発注データ
      currentOrders = orders.filter(order => 
        order.店舗ID === storeId && 
        order.発注日 && 
        new Date(order.発注日).toDateString() === new Date().toDateString()
      );

      renderOrders(currentOrders);
    } catch (error) {
      showError('発注データの読み込みに失敗しました');
    }
  }

  // 発注送信処理
  async function sendOrders() {
    const selectedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');

    if (selectedCheckboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    const selectedIds = Array.from(selectedCheckboxes).map(cb => cb.dataset.id);
    const selectedOrders = currentOrders.filter(order => selectedIds.includes(order.発注ID));

    // 送信済みデータのチェック
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');
    if (alreadySent.length > 0) {
      showError('この発注データは既に送信済みです。重複送信はできません。');
      return;
    }

    // 発注数量0のチェック
    const zeroQuantity = selectedOrders.filter(order => (order.発注数量 || 0) === 0);
    if (zeroQuantity.length > 0) {
      const proceed = confirm(`発注数量が0の商品が${zeroQuantity.length}件含まれています。これらを除外して送信しますか？`);
      if (!proceed) return;

      // 発注数量0の商品を除外
      const validOrders = selectedOrders.filter(order => (order.発注数量 || 0) > 0);
      if (validOrders.length === 0) {
        showError('送信可能な発注データがありません');
        return;
      }
    }

    showSendDialog(selectedOrders);
  }

  // 送信確認ダイアログの表示
  function showSendDialog(orders) {
    const dialog = container.querySelector('#send-dialog');
    const message = container.querySelector('#send-confirm-message');

    const totalAmount = orders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    message.innerHTML = `
      <p>以下の発注データを送信しますか？</p>
      <ul style="margin: 10px 0; padding-left: 20px;">
        <li>選択件数: ${orders.length}件</li>
        <li>合計金額: ¥${totalAmount.toLocaleString()}</li>
      </ul>
    `;

    dialog.classList.remove('hidden');

    // 確認ボタンのイベント
    const confirmBtn = container.querySelector('#btn-confirm');
    const cancelBtn = container.querySelector('#btn-cancel');

    const handleConfirm = async () => {
      dialog.classList.add('hidden');
      await executeSend(orders);
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    const handleCancel = () => {
      dialog.classList.add('hidden');
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    confirmBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // 実際の送信処理
  async function executeSend(orders) {
    try {
      let successCount = 0;
      let failCount = 0;

      for (const order of orders) {
        try {
          await window.aivicApi.update(7, order.発注ID, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user-id'
          });
          successCount++;
        } catch (error) {
          failCount++;
        }
      }

      if (successCount > 0) {
        showSuccess(`${successCount}件の発注を正常に送信しました`);
      }

      if (failCount > 0) {
        showError(`${failCount}件の発注送信に失敗しました`);
      }

      // データを再読み込み
      const storeId = container.querySelector('#store-select').value;
      await loadOrdersByStore(storeId);

    } catch (error) {
      showError('発注送信処理中にエラーが発生しました');
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvData = [headers];

    currentOrders.forEach(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      csvData.push([
        product.商品コード || '',
        product.商品名 || '',
        order.予測数量 || 0,
        order.発注数量 || 0,
        getSupplierName(product.仕入先ID),
        order.発注金額 || 0,
        order.発注ステータス || '送信待ち'
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    successDiv.classList.add('hidden');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    errorDiv.classList.add('hidden');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');

    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 5000);
  }

  // イベントリスナーの設定
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersByStore(e.target.value);
  });

  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
    });
    updateSummary();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      updateSummary();

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');
      const selectAllCheckbox = container.querySelector('#select-all');

      selectAllCheckbox.checked = allCheckboxes.length > 0 && allCheckboxes.length === checkedCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < allCheckboxes.length;
    }
  });

  container.querySelector('#btn-send').addEventListener('click', sendOrders);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 初期データの読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentOrderDate = '';
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let demandForecasts = [];
  let products = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;
  currentOrderDate = today;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(s => s.有効フラグ);
        renderStoreOptions();
      }

      // 商品マスタ読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        products = productData.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        renderCategoryOptions();
      }

      // 需要予測結果読み込み
      const forecastData = await window.aivicApi.list(8);
      if (forecastData) {
        demandForecasts = forecastData;
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-filter');
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';

    // 商品からカテゴリを抽出（重複除去）
    const uniqueCategories = [...new Set(products.map(p => p.商品カテゴリID))];
    uniqueCategories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-8)}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProducts() {
    const tbody = container.querySelector('#order-table-body');

    if (!currentStoreId) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      updateExecuteButtons();
      return;
    }

    if (currentProducts.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">データがありません</td></tr>';
      updateExecuteButtons();
      return;
    }

    tbody.innerHTML = currentProducts.map(product => {
      const forecast = demandForecasts.find(f => 
        f.店舗ID === currentStoreId && 
        f.商品ID === product.商品ID &&
        f.予測対象日 === currentOrderDate
      );

      const predictedDemand = forecast ? forecast.予測数量 : 0;
      const recommendedOrder = forecast ? forecast.推奨発注数量 : 0;
      const currentStock = Math.floor(Math.random() * 50); // 仮の在庫数

      return `
        <tr data-product-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}" /></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${predictedDemand}</td>
          <td style="text-align: right;">${recommendedOrder}</td>
          <td style="text-align: right;">${currentStock}</td>
          <td>
            <input type="number" 
                   class="input order-quantity" 
                   data-product-id="${product.商品ID}"
                   data-unit-price="${product.単価 || 0}"
                   value="${recommendedOrder}" 
                   min="0" 
                   step="1"
                   style="width: 80px;" />
          </td>
          <td style="text-align: right;">${(product.単価 || 0).toLocaleString()}円</td>
          <td style="text-align: right;">
            <span class="order-amount" data-product-id="${product.商品ID}">
              ${((product.単価 || 0) * recommendedOrder).toLocaleString()}円
            </span>
          </td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
    updateExecuteButtons();
  }

  // 商品データを更新
  async function updateProductList() {
    if (!currentStoreId) {
      currentProducts = [];
      renderProducts();
      return;
    }

    const categoryFilter = container.querySelector('#category-filter').value;

    // カテゴリフィルターを適用
    let filteredProducts = products;
    if (categoryFilter) {
      filteredProducts = products.filter(p => p.商品カテゴリID === categoryFilter);
    }

    currentProducts = filteredProducts;
    renderProducts();
  }

  // 合計金額を更新
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const unitPrice = parseInt(input.dataset.unitPrice) || 0;
      total += quantity * unitPrice;

      // 個別金額も更新
      const amountSpan = container.querySelector(`.order-amount[data-product-id="${input.dataset.productId}"]`);
      if (amountSpan) {
        amountSpan.textContent = (quantity * unitPrice).toLocaleString() + '円';
      }
    });

    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // 発注実行ボタンの状態を更新
  function updateExecuteButtons() {
    const executeBtn = container.querySelector('#btn-execute-order');
    const executeSelectedBtn = container.querySelector('#btn-execute-selected');
    const hasProducts = currentProducts.length > 0 && currentStoreId;
    const hasSelectedProducts = container.querySelectorAll('.product-checkbox:checked').length > 0;

    executeBtn.disabled = !hasProducts;
    executeSelectedBtn.disabled = !hasSelectedProducts;
  }

  // バリデーション
  function validateOrderData(selectedOnly = false) {
    const errors = [];

    if (!currentStoreId) {
      errors.push('店舗を選択してください');
    }

    if (!currentOrderDate) {
      errors.push('発注日付を選択してください');
    } else if (new Date(currentOrderDate) < new Date(today)) {
      errors.push('発注日付は本日以降の日付を選択してください');
    }

    const quantityInputs = selectedOnly ? 
      container.querySelectorAll('.product-checkbox:checked').length > 0 ?
        Array.from(container.querySelectorAll('.order-quantity')).filter(input => {
          const checkbox = container.querySelector(`.product-checkbox[data-product-id="${input.dataset.productId}"]`);
          return checkbox && checkbox.checked;
        }) :
        [] :
      container.querySelectorAll('.order-quantity');

    if (quantityInputs.length === 0) {
      errors.push(selectedOnly ? '発注する商品を選択してください' : '発注対象商品がありません');
    }

    quantityInputs.forEach(input => {
      const value = input.value.trim();
      const quantity = parseFloat(value);

      if (value === '') {
        errors.push('発注数量を入力してください');
      } else if (isNaN(quantity)) {
        errors.push('発注数量は数値を入力してください');
      } else if (quantity < 0) {
        errors.push('発注数量は正の値を入力してください');
      } else if (quantity === 0) {
        errors.push('発注数量は1以上の値を入力してください');
      } else if (!Number.isInteger(quantity)) {
        errors.push('発注数量は整数を入力してください');
      }
    });

    return errors;
  }

  // 発注確認ダイアログを表示
  function showOrderConfirmDialog(selectedOnly = false) {
    const errors = validateOrderData(selectedOnly);
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const quantityInputs = selectedOnly ? 
      Array.from(container.querySelectorAll('.order-quantity')).filter(input => {
        const checkbox = container.querySelector(`.product-checkbox[data-product-id="${input.dataset.productId}"]`);
        return checkbox && checkbox.checked && (parseInt(input.value) || 0) > 0;
      }) :
      Array.from(container.querySelectorAll('.order-quantity')).filter(input => (parseInt(input.value) || 0) > 0);

    let totalAmount = 0;
    const orderItems = quantityInputs.map(input => {
      const productId = input.dataset.productId;
      const quantity = parseInt(input.value) || 0;
      const unitPrice = parseInt(input.dataset.unitPrice) || 0;
      const amount = quantity * unitPrice;
      totalAmount += amount;

      const product = currentProducts.find(p => p.商品ID === productId);
      return {
        productId,
        productCode: product?.商品コード || '',
        productName: product?.商品名|| '',
        quantity,
        unitPrice,
        amount
      };
    });

    const storeName = stores.find(s => s.店舗ID === currentStoreId)?.店舗名 || '';

    content.innerHTML = `
      <div style="margin-bottom: 20px;">
        <p><strong>店舗:</strong> ${storeName}</p>
        <p><strong>発注日付:</strong> ${currentOrderDate}</p>
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td>${item.productCode}</td>
                <td>${item.productName}</td>
                <td style="text-align: right;">${item.quantity}</td>
                <td style="text-align: right;">${item.unitPrice.toLocaleString()}円</td>
                <td style="text-align: right;">${item.amount.toLocaleString()}円</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div style="text-align: right; margin-top: 10px; font-weight: bold;">
        合計: ${totalAmount.toLocaleString()}円
      </div>
    `;

    dialog.classList.remove('hidden');

    // 確認ダイアログのボタンイベント
    const confirmBtn = container.querySelector('#btn-confirm-execute');
    const cancelBtn = container.querySelector('#btn-confirm-cancel');

    confirmBtn.onclick = () => executeOrder(orderItems);
    cancelBtn.onclick = () => dialog.classList.add('hidden');
  }

  // 発注実行
  async function executeOrder(orderItems) {
    try {
      const dialog = container.querySelector('#order-confirm-dialog');
      dialog.classList.add('hidden');

      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderData = {
          店舗ID: currentStoreId,
          商品ID: item.productId,
          発注日: currentOrderDate,
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 3日後
          発注数量: item.quantity,
          発注単価: item.unitPrice,
          発注金額: item.amount,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(9, orderData);
      }

      alert('発注が正常に実行されました');

      // 発注数量をリセット
      container.querySelectorAll('.order-quantity').forEach(input => {
        input.value = '0';
      });
      container.querySelectorAll('.product-checkbox').forEach(checkbox => {
        checkbox.checked = false;
      });
      container.querySelector('#select-all').checked = false;

      updateTotalAmount();
      updateExecuteButtons();

    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateProductList();
  });

  // 発注日付選択
  container.querySelector('#order-date').addEventListener('change', (e) => {
    currentOrderDate = e.target.value;
    updateProductList();
  });

  // カテゴリフィルター
  container.querySelector('#category-filter').addEventListener('change', () => {
    updateProductList();
  });

  // 表示更新ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    updateProductList();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = e.target.checked;
    });
    updateExecuteButtons();
  });

  // 商品チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      updateExecuteButtons();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.product-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.product-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = true;
      } else {
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  // 発注数量入力
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      updateTotalAmount();
    }
  });

  // 発注実行ボタン
  container.querySelector('#btn-execute-order').addEventListener('click', () => {
    showOrderConfirmDialog(false);
  });

  // 選択商品発注実行ボタン
  container.querySelector('#btn-execute-selected').addEventListener('click', () => {
    showOrderConfirmDialog(true);
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // 再描画関数の定義
  function renderAccuracyRanking(data) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((item, index) => {
      const mape = parseFloat(item.mape || 0);
      const accuracyClass = mape <= 10 ? 'accuracy-good' : mape <= 20 ? 'accuracy-warning' : 'accuracy-danger';

      return `
        <tr data-id="${item.id}">
          <td>${index + 1}</td>
          <td>${item.store_name || ''}</td>
          <td>${item.product_name || ''}</td>
          <td>${item.category || ''}</td>
          <td class="${accuracyClass}">${mape.toFixed(2)}%</td>
          <td>${parseFloat(item.rmse || 0).toFixed(2)}</td>
          <td>${item.prediction_count || 0}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${item.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // サマリー更新
  function updateSummary(data) {
    if (!data || data.length === 0) {
      container.querySelector('#overall-accuracy').textContent = '--';
      container.querySelector('#overall-rmse').textContent = '--';
      container.querySelector('#total-products').textContent = '0';
      container.querySelector('#alert-count').textContent = '0';
      return;
    }

    const totalMape = data.reduce((sum, item) => sum + parseFloat(item.mape || 0), 0);
    const avgMape = totalMape / data.length;

    const totalRmse = data.reduce((sum, item) => sum + parseFloat(item.rmse || 0), 0);
    const avgRmse = totalRmse / data.length;

    const alertCount = data.filter(item => parseFloat(item.mape || 0) > 20).length;

    container.querySelector('#overall-accuracy').textContent = avgMape.toFixed(2) + '%';
    container.querySelector('#overall-rmse').textContent = avgRmse.toFixed(2);
    container.querySelector('#total-products').textContent = data.length.toString();
    container.querySelector('#alert-count').textContent = alertCount.toString();
  }

  // アラート更新
  function updateAlerts(data) {
    const alertList = container.querySelector('#alert-list');
    const alerts = data.filter(item => parseFloat(item.mape || 0) > 20);

    if (alerts.length === 0) {
      alertList.innerHTML = '<p class="muted">現在アラートはありません</p>';
      return;
    }

    alertList.innerHTML = alerts.map(alert => `
      <div class="alert-item">
        <div class="alert-title">精度低下アラート</div>
        <div class="alert-details">
          ${alert.store_name} - ${alert.product_name}: MAPE ${parseFloat(alert.mape).toFixed(2)}% (閾値: 20%)
        </div>
      </div>
    `).join('');
  }

  // グラフ描画
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // データポイント描画
    if (data.length > 1) {
      const maxMape = Math.max(...data.map(d => parseFloat(d.mape || 0)));
      const stepX = chartWidth / (data.length - 1);

      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((item, index) => {
        const x = margin.left + index * stepX;
        const y = margin.top + chartHeight - (parseFloat(item.mape || 0) / maxMape) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('時間', canvas.width / 2, canvas.height - 5);

    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('MAPE (%)', 0, 0);
    ctx.restore();
  }

  function drawPredictionVsActualChart(data) {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(margin.left + 20, margin.top + 10, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', margin.left + 40, margin.top + 15);

    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(margin.left + 100, margin.top + 10, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', margin.left + 120, margin.top + 15);
  }

  // 店舗選択肢の初期化
  function initializeStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeSelect.innerHTML = '<option value="">全店舗</option>' +
      stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
  }

  // データ読み込み
  async function loadData() {
    try {
      container.querySelector('#error-message').classList.add('hidden');
      const data = await window.aivicApi.list(4); // 需要予測結果テーブル

      if (data) {
        // 予測精度データに変換
        currentData = data.map((item, index) => ({
          id: item.id,
          store_name: `店舗${index % 5 + 1}`,
          product_name: `商品${index % 10 + 1}`,
          category: ['食品', '日用品', '衣料品'][index % 3],
          mape: (Math.random() * 30 + 5).toFixed(2),
          rmse: (Math.random() * 50 + 10).toFixed(2),
          prediction_count: Math.floor(Math.random() * 100 + 10)
        }));

        applyFilters();
      } else {
        showError();
      }
    } catch (error) {
      showError();
    }
  }

  function showError() {
    container.querySelector('#error-message').classList.remove('hidden');
  }

  // フィルター適用
  function applyFilters() {
    const period = container.querySelector('#period-select').value;
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.store_id === storeId);
    }

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    // ソート適用
    if (sortColumn) {
      filteredData.sort((a, b) => {
        let aVal = a[sortColumn];
        let bVal = b[sortColumn];

        if (sortColumn === 'mape' || sortColumn === 'rmse' || sortColumn === 'prediction_count') {
          aVal = parseFloat(aVal) || 0;
          bVal = parseFloat(bVal) || 0;
        }

        if (sortDirection === 'asc') {
          return aVal > bVal ? 1 : -1;
        } else {
          return aVal < bVal ? 1 : -1;
        }
      });
    }

    renderAccuracyRanking(filteredData);
    updateSummary(filteredData);
    updateAlerts(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawPredictionVsActualChart(filteredData);
  }

  // ソート処理
  function handleSort(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    // ソートインジケーター更新
    container.querySelectorAll('.sortable').forEach(th => {
      th.classList.remove('sort-asc', 'sort-desc');
    });

    const currentTh = container.querySelector(`[data-sort="${column}"]`);
    if (currentTh) {
      currentTh.classList.add(sortDirection === 'asc' ? 'sort-asc' : 'sort-desc');
    }

    applyFilters();
  }

  // CSVエクスポート
  function exportToCsv() {
    const headers = ['順位', '店舗名', '商品名', 'カテゴリ', 'MAPE (%)', 'RMSE', '予測回数'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' +
      currentData.map((item, index) => [
        index + 1,
        `"${item.store_name}"`,
        `"${item.product_name}"`,
        `"${item.category}"`,
        item.mape,
        item.rmse,
        item.prediction_count
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '予測精度レポート.csv';
    link.click();
  }

  // 初期化
  initializeStoreOptions();
  loadData();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-retry').addEventListener('click', loadData);

  container.querySelector('#btn-export-report').addEventListener('click', exportToCsv);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.sort;
      handleSort(column);
    }

    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });

  // 期間変更時の自動更新
  container.querySelector('#period-select').addEventListener('change', applyFilters);
  container.querySelector('#store-select').addEventListener('change', applyFilters);
  container.querySelector('#category-select').addEventListener('change', applyFilters);
}

function(container, apiUrl, tables) {
  let currentModelData = null;
  let currentExecutionId = null;
  let progressInterval = null;

  // DOM要素の取得
  const modelSelect = container.querySelector('#model-select');
  const modelDetails = container.querySelector('#model-details');
  const modelInfo = container.querySelector('#model-info');
  const storeList = container.querySelector('#store-list');
  const selectAllStores = container.querySelector('#select-all-stores');
  const startDatetime = container.querySelector('#start-datetime');
  const backupEnabled = container.querySelector('#backup-enabled');
  const retentionDays = container.querySelector('#retention-days');
  const validationResults = container.querySelector('#validation-results');
  const validationInfo = container.querySelector('#validation-info');
  const impactAnalysis = container.querySelector('#impact-analysis');
  const impactInfo = container.querySelector('#impact-info');
  const btnExecute = container.querySelector('#btn-execute');
  const btnValidate = container.querySelector('#btn-validate');
  const btnRollback = container.querySelector('#btn-rollback');
  const progressSection = container.querySelector('#progress-section');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressStatus = container.querySelector('#progress-status');
  const logSection = container.querySelector('#log-section');
  const logDisplay = container.querySelector('#log-display');
  const errorMessage = container.querySelector('#error-message');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // ログ追加関数
  function addLog(message) {
    const timestamp = new Date().toLocaleString();
    logDisplay.textContent += `[${timestamp}] ${message}\n`;
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // 進捗更新関数
  function updateProgress(percent, status) {
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}%`;
    progressStatus.textContent = status;
  }

  // モデル一覧の初期化
  async function initializeModels() {
    try {
      // サンプルモデルデータを生成
      const models = [
        {
          id: 'model-001',
          name: 'AI需要予測モデル v2.1',
          version: '2.1.0',
          accuracy: 92.5,
          status: '検証済み',
          createdAt: '2024-01-15T10:30:00',
          description: '季節要因と天候データを考慮した高精度予測モデル'
        },
        {
          id: 'model-002',
          name: 'AI需要予測モデル v2.0',
          version: '2.0.0',
          accuracy: 89.3,
          status: '本番適用中',
          createdAt: '2024-01-10T14:20:00',
          description: '基本的な需要予測機能を提供するモデル'
        }
      ];

      modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';
      models.forEach(model => {
        const option = document.createElement('option');
        option.value = model.id;
        option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
        option.dataset.modelData = JSON.stringify(model);
        modelSelect.appendChild(option);
      });
    } catch (error) {
      showError('モデル一覧の取得に失敗しました');
    }
  }

  // 店舗一覧の初期化
  async function initializeStores() {
    try {
      const stores = await window.aivicApi.list(1) || tables[1]?.records || [];

      storeList.innerHTML = '';
      stores.forEach(store => {
        const div = document.createElement('div');
        div.style.marginBottom = '8px';
        div.innerHTML = `
          <label style="color: var(--text); cursor: pointer;">
            <input type="checkbox" class="store-checkbox" value="${store.id}" style="margin-right: 8px;">
            ${store.店舗名 || store.storeName || `店舗${store.id}`} (${store.店舗コード || store.storeCode || store.id})
          </label>
        `;
        storeList.appendChild(div);
      });
    } catch (error) {
      showError('店舗一覧の取得に失敗しました');
    }
  }

  // モデル選択時の処理
  modelSelect.addEventListener('change', function() {
    const selectedOption = this.options[this.selectedIndex];
    if (selectedOption.value && selectedOption.dataset.modelData) {
      currentModelData = JSON.parse(selectedOption.dataset.modelData);

      // モデル詳細情報を表示
      modelInfo.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
          <div><strong>モデル名:</strong> ${currentModelData.name}</div>
          <div><strong>バージョン:</strong> ${currentModelData.version}</div>
          <div><strong>予測精度:</strong> ${currentModelData.accuracy}%</div>
          <div><strong>ステータス:</strong> ${currentModelData.status}</div>
          <div><strong>作成日時:</strong> ${new Date(currentModelData.createdAt).toLocaleString()}</div>
          <div style="grid-column: 1 / -1;"><strong>説明:</strong> ${currentModelData.description}</div>
        </div>
      `;
      modelDetails.style.display = 'block';

      // 検証ボタンを有効化
      btnValidate.disabled = false;
    } else {
      currentModelData = null;
      modelDetails.style.display = 'none';
      validationResults.style.display = 'none';
      impactAnalysis.style.display = 'none';
      btnValidate.disabled = true;
      btnExecute.disabled = true;
    }
  });

  // 全店舗選択チェックボックスの処理
  selectAllStores.addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // 適用前検証実行
  btnValidate.addEventListener('click', async function() {
    if (!currentModelData) {
      showError('モデルが選択されていません');
      return;
    }

    try {
      btnValidate.disabled = true;
      btnValidate.textContent = '検証中...';

      // 検証処理をシミュレート
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 検証結果を表示
      const validationPassed = Math.random() > 0.2; // 80%の確率で成功

      validationInfo.innerHTML = `
        <div style="margin-bottom: 15px;">
          <div style="display: flex; align-items: center; margin-bottom: 10px;">
            <span style="color: ${validationPassed ? '#4CAF50' : '#f44336'}; font-weight: bold;">
              ${validationPassed ? '✓ 検証成功' : '✗ 検証失敗'}
            </span>
          </div>
          <div style="margin-bottom: 10px;"><strong>データ品質チェック:</strong> ${validationPassed ? '正常' : 'エラー検出'}</div>
          <div style="margin-bottom: 10px;"><strong>精度閾値チェック:</strong> ${validationPassed ? '基準値クリア' : '基準値未達'}</div>
          <div style="margin-bottom: 10px;"><strong>互換性チェック:</strong> ${validationPassed ? '問題なし' : '互換性エラー'}</div>
        </div>
      `;

      validationResults.style.display = 'block';

      if (validationPassed) {
        // 影響範囲分析を表示
        const selectedStores = container.querySelectorAll('.store-checkbox:checked');
        impactInfo.innerHTML = `
          <div>
            <div style="margin-bottom: 10px;"><strong>対象店舗数:</strong> ${selectedStores.length}店舗</div>
            <div style="margin-bottom: 10px;"><strong>予想処理時間:</strong> 約${Math.ceil(selectedStores.length * 0.5)}分</div>
            <div style="margin-bottom: 10px;"><strong>影響する予測対象商品:</strong> 約${selectedStores.length * 150}商品</div>
            <div style="margin-bottom: 10px;"><strong>システム負荷:</strong> 中程度</div>
          </div>
        `;
        impactAnalysis.style.display = 'block';
        btnExecute.disabled = false;
      } else {
        impactAnalysis.style.display = 'none';
        btnExecute.disabled = true;
      }

    } catch (error) {
      showError('検証処理でエラーが発生しました');
    } finally {
      btnValidate.disabled = false;
      btnValidate.textContent = '適用前検証実行';
    }
  });

  // 適用実行処理
  btnExecute.addEventListener('click', async function() {
    // バリデーション
    if (!currentModelData) {
      showError('モデルが選択されていません');
      return;
    }

    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    if (selectedStores.length === 0) {
      showError('店舗が選択されていません');
      return;
    }

    const startTime = startDatetime.value;
    if (!startTime) {
      showError('適用開始日時が未入力です');
      return;
    }

    const startDate = new Date(startTime);
    const now = new Date();
    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!confirm(`${currentModelData.name} を ${selectedStores.length}店舗に適用しますか？`)) {
      return;
    }

    try {
      btnExecute.disabled = true;
      btnExecute.textContent = '適用中...';
      progressSection.style.display = 'block';
      logSection.style.display = 'block';

      currentExecutionId = 'exec-' + Date.now();

      addLog('モデル本番適用処理を開始しました');
      addLog(`対象モデル: ${currentModelData.name}`);
      addLog(`対象店舗数: ${selectedStores.length}店舗`);
      addLog(`バックアップ設定: ${backupEnabled.checked ? '有効' : '無効'}`);

      // 進捗シミュレーション
      const steps = [
        { percent: 10, status: 'モデル検証中...', delay: 1000 },
        { percent: 25, status: 'バックアップ作成中...', delay: 1500 },
        { percent: 40, status: 'モデルデプロイ中...', delay: 2000 },
        { percent: 60, status: '店舗別設定適用中...', delay: 2500 },
        { percent: 80, status: '動作確認中...', delay: 1500 },
        { percent: 100, status: '適用完了', delay: 1000 }
      ];

      for (const step of steps) {
        await new Promise(resolve => setTimeout(resolve, step.delay));
        updateProgress(step.percent, step.status);
        addLog(step.status);
      }

      addLog('モデル本番適用処理が正常に完了しました');
      btnRollback.disabled = false;

    } catch (error) {
      showError('適用処理中にシステムエラーが発生しました');
      addLog(`エラー: ${error.message}`);
    } finally {
      btnExecute.disabled = false;
      btnExecute.textContent = '適用実行';
    }
  });

  // ロールバック実行処理
  btnRollback.addEventListener('click', async function() {
    if (!confirm('前のバージョンにロールバックしますか？')) {
      return;
    }

    try {
      btnRollback.disabled = true;
      btnRollback.textContent = 'ロールバック中...';

      addLog('ロールバック処理を開始しました');

      // ロールバック進捗シミュレーション
      const rollbackSteps = [
        { percent: 20, status: 'バックアップ確認中...', delay: 1000 },
        { percent: 50, status: '前バージョン復元中...', delay: 1500 },
        { percent: 80, status: '動作確認中...', delay: 1000 },
        { percent: 100, status: 'ロールバック完了', delay: 500 }
      ];

      for (const step of rollbackSteps) {
        await new Promise(resolve => setTimeout(resolve, step.delay));
        updateProgress(step.percent, step.status);
        addLog(step.status);
      }

      addLog('ロールバック処理が正常に完了しました');

    } catch (error) {
      showError('ロールバック処理でエラーが発生しました');
      addLog(`エラー: ${error.message}`);
    } finally {
      btnRollback.disabled = false;
      btnRollback.textContent = 'ロールバック実行';
    }
  });

  // 現在時刻を適用開始日時のデフォルト値に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  startDatetime.value = now.toISOString().slice(0, 16);

  // 初期化
  initializeModels();
  initializeStores();
}
